const WS = require('ws');
const fs = require('fs');
const target = JSON.parse(fs.readFileSync('/tmp/yinshi-Profile-5-target.json'));
const ws = new WS(target.webSocketDebuggerUrl);
let sequence = 0;
const pending = new Map();
ws.on('message', (data) => {
  const message = JSON.parse(data);
  if (message.id && pending.has(message.id)) {
    pending.get(message.id)(message);
    pending.delete(message.id);
  }
});
const call = (method, params = {}) => new Promise((resolve) => {
  const id = ++sequence;
  pending.set(id, resolve);
  ws.send(JSON.stringify({ id, method, params }));
});
ws.on('open', async () => {
  await call('Page.navigate', { url: 'https://yinshi.io/auth/github/install' });
  await new Promise((resolve) => setTimeout(resolve, 5000));
  const history = await call('Page.getNavigationHistory');
  const entry = [...history.result.entries]
    .reverse()
    .find((item) => item.url.includes('github.com/apps/yinshi-io/installations/new'));
  if (!entry) throw new Error('install redirect missing');
  const state = new URL(entry.url).searchParams.get('state');
  if (!state) throw new Error('install state missing');
  const callback = new URL('https://yinshi.io/auth/github/install/callback');
  callback.searchParams.set('installation_id', '117632573');
  callback.searchParams.set('setup_action', 'install');
  callback.searchParams.set('state', state);
  await call('Page.navigate', { url: callback.toString() });
  await new Promise((resolve) => setTimeout(resolve, 6000));
  const result = await call('Runtime.evaluate', {
    expression: 'document.title + " | " + location.href.replace(/([?&](state|code)=)[^&]+/g, "$1[redacted]") + " | " + document.body.innerText.slice(0, 500)',
    returnByValue: true,
  });
  console.log(result.result.result.value);
  ws.close();
});

